def caesar_shift(s, shift):
    out = []
    for ch in s:
        if ch.isalpha():
            base = 65 if ch.isupper() else 97
            out.append(chr((ord(ch) - base + shift) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

def rot13(s):
    out = []
    for ch in s:
        if ch.isalpha():
            base = 65 if ch.isupper() else 97
            out.append(chr((ord(ch) - base + 13) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

def atbash_cipher(s):
    out = []
    for ch in s:
        if ch.isupper():
            out.append(chr(ord('Z') - (ord(ch) - ord('A'))))
        elif ch.islower():
            out.append(chr(ord('z') - (ord(ch) - ord('a'))))
        else:
            out.append(ch)
    return ''.join(out)

def run_length_encode(s):
    if not s:
        return ""
    out = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(prev + str(count))
            prev = ch
            count = 1
    out.append(prev + str(count))
    return ''.join(out)

def run_length_decode(s):
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        j = i + 1
        num = ""
        while j < len(s) and s[j].isdigit():
            num += s[j]
            j += 1
        out.append(ch * int(num))
        i = j
    return ''.join(out)

def swap_case_custom(s):
    out = []
    for ch in s:
        if ch.isupper():
            out.append(ch.lower())
        elif ch.islower():
            out.append(ch.upper())
        else:
            out.append(ch)
    return ''.join(out)

def longest_word(s):
    words = s.split()
    if not words:
        return ""
    best = words[0]
    for w in words[1:]:
        if len(w) > len(best):
            best = w
    return best

def shortest_word(s):
    words = s.split()
    if not words:
        return ""
    best = words[0]
    for w in words[1:]:
        if len(w) < len(best):
            best = w
    return best

def most_common_word(s):
    words = s.lower().split()
    if not words:
        return ""
    counts = {}
    order = []
    for w in words:
        if w not in counts:
            counts[w] = 0
            order.append(w)
        counts[w] += 1
    best = order[0]
    for w in order[1:]:
        if counts[w] > counts[best]:
            best = w
    return best

def sentence_case(s):
    s = s.lower()
    for i, ch in enumerate(s):
        if ch.isalpha():
            return s[:i] + ch.upper() + s[i+1:]
    return s

def compress_consecutive_duplicates(s):
    if not s:
        return ""
    out = [s[0]]
    for ch in s[1:]:
        if ch != out[-1]:
            out.append(ch)
    return ''.join(out)
